from __future__ import annotations

from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any, Dict, Optional
import json
import uuid

SCHEMA_VERSION = "lumina-continuity-correlation-r1"


def read_marker(path: Path) -> Dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


@dataclass(frozen=True)
class ContinuityCorrelation:
    schema_version: str
    correlation_id: str
    project_slug: Optional[str]
    harbor_session_id: Optional[str]
    runtime_session_id: Optional[str]
    restore_session_id: Optional[str]
    host_session_id: Optional[str]
    authority_boundary: str

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


def active_workspace(state_root: Path) -> Dict[str, Optional[str]]:
    project = read_marker(state_root / "active_project.json")
    session = read_marker(state_root / "active_session.json")
    project_slug = project.get("active_project_slug")
    session_project = session.get("project_slug")
    if project_slug and session_project and project_slug != session_project:
        raise ValueError("active project and session markers disagree")
    return {
        "project_slug": str(project_slug or session_project) if (project_slug or session_project) else None,
        "harbor_session_id": str(session.get("active_session_id")) if session.get("active_session_id") else None,
    }


def create_correlation(
    *,
    state_root: Optional[Path] = None,
    project_slug: Optional[str] = None,
    harbor_session_id: Optional[str] = None,
    runtime_session_id: Optional[str] = None,
    restore_session_id: Optional[str] = None,
    host_session_id: Optional[str] = None,
    correlation_id: Optional[str] = None,
) -> ContinuityCorrelation:
    if state_root is not None:
        active = active_workspace(state_root)
        project_slug = project_slug or active["project_slug"]
        harbor_session_id = harbor_session_id or active["harbor_session_id"]
    if not any([harbor_session_id, runtime_session_id, restore_session_id, host_session_id]):
        raise ValueError("at least one session reference is required")
    return ContinuityCorrelation(
        schema_version=SCHEMA_VERSION,
        correlation_id=correlation_id or f"lumina-{uuid.uuid4().hex}",
        project_slug=project_slug,
        harbor_session_id=harbor_session_id,
        runtime_session_id=runtime_session_id,
        restore_session_id=restore_session_id,
        host_session_id=host_session_id,
        authority_boundary="Correlation does not transfer governance, canon, checkpoint, or capability authority.",
    )

from __future__ import annotations

from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional
import hashlib
import json
import uuid


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def canonical_json(payload: Dict[str, Any]) -> str:
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def sha256_file(path: str | Path) -> str:
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()


@dataclass
class GovernanceIntegrityRecord:
    event_id: str
    timestamp_utc: str
    prev_event_hash: Optional[str]
    record_hash: str
    event_type: str
    session_identifier: str
    previous_mode: Optional[str] = None
    new_mode: Optional[str] = None
    allowed: Optional[bool] = None
    reason: Optional[str] = None
    requested_action: Optional[str] = None
    artifact_delta: Optional[Any] = None
    canonical_change: Optional[bool] = None
    validation_reference: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None

    def to_dict(self) -> Dict[str, Any]:
        payload = asdict(self)
        payload["metadata"] = dict(self.metadata or {})
        return payload


class GovernanceIntegrityChain:
    """Append-only governance rail with record hashing and chain verification."""

    HASH_EXCLUDED_FIELDS = {"record_hash"}

    def __init__(self, log_path: str | Path, *, seed_committed_canon: bool = True):
        self.log_path = Path(log_path)
        self.seed_committed_canon = seed_committed_canon
        self.log_path.parent.mkdir(parents=True, exist_ok=True)

    def _rows(self) -> List[Dict[str, Any]]:
        if not self.log_path.exists():
            return []
        rows: List[Dict[str, Any]] = []
        with self.log_path.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line:
                    rows.append(json.loads(line))
        return rows

    def latest_record(self) -> Optional[Dict[str, Any]]:
        rows = self._rows()
        return rows[-1] if rows else None

    def latest_event_hash(self) -> Optional[str]:
        latest = self.latest_record()
        return latest.get("record_hash") if latest else None

    def compute_checkpoint_hash(self, checkpoint_path: str | Path) -> str:
        return sha256_file(checkpoint_path)

    def _record_payload_for_hash(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        return {k: v for k, v in payload.items() if k not in self.HASH_EXCLUDED_FIELDS}

    def _compute_record_hash(self, payload: Dict[str, Any]) -> str:
        return sha256_text(canonical_json(self._record_payload_for_hash(payload)))

    @staticmethod
    def _repo_root() -> Path:
        return Path(__file__).resolve().parents[4]

    def _seed_committed_canon_if_local_promotion(self, event_type: str) -> None:
        if event_type != "promotion" or not self.seed_committed_canon:
            return
        root = self._repo_root()
        try:
            self.log_path.resolve().relative_to((root / ".lumina_state").resolve())
        except ValueError:
            return
        committed = root / "artifacts/runtime_truth/current/governance_chain_0001.jsonl"
        if not committed.is_file():
            raise ValueError("committed promotion governance is missing")
        source = GovernanceIntegrityChain(committed, seed_committed_canon=False)
        if not source.verify_chain()["valid"] or not source._rows():
            raise ValueError("committed promotion governance is invalid")
        rows = self._rows()
        if rows:
            if rows[:len(source._rows())] != source._rows() or not self.verify_chain()["valid"]:
                raise ValueError("local governance does not extend valid committed governance; use fresh promotion state")
            return
        self.log_path.write_bytes(committed.read_bytes())

    def append_verified(
        self,
        *,
        event_type: str,
        session_identifier: str,
        previous_mode: Optional[str] = None,
        new_mode: Optional[str] = None,
        allowed: Optional[bool] = None,
        reason: Optional[str] = None,
        requested_action: Optional[str] = None,
        artifact_delta: Optional[Any] = None,
        canonical_change: Optional[bool] = None,
        validation_reference: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        self._seed_committed_canon_if_local_promotion(event_type)
        record = {
            "event_id": f"gov-{uuid.uuid4().hex[:16]}",
            "timestamp_utc": utc_now(),
            "prev_event_hash": self.latest_event_hash(),
            "event_type": event_type,
            "session_identifier": session_identifier,
            "previous_mode": previous_mode,
            "new_mode": new_mode,
            "allowed": allowed,
            "reason": reason,
            "requested_action": requested_action,
            "artifact_delta": artifact_delta,
            "canonical_change": canonical_change,
            "validation_reference": validation_reference,
            "metadata": dict(metadata or {}),
        }
        record["record_hash"] = self._compute_record_hash(record)
        with self.log_path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(record) + "\n")
        return record

    def verify_chain(self) -> Dict[str, Any]:
        rows = self._rows()
        errors: List[str] = []
        warnings: List[str] = []
        previous_hash: Optional[str] = None
        chain_tainted = False

        for idx, row in enumerate(rows):
            expected_prev = previous_hash
            actual_prev = row.get("prev_event_hash")
            if actual_prev != expected_prev:
                errors.append(
                    f"row {idx}: prev_event_hash mismatch (expected {expected_prev}, got {actual_prev})"
                )
                chain_tainted = True

            actual_hash = row.get("record_hash")
            expected_hash = self._compute_record_hash(row)
            if not actual_hash:
                errors.append(f"row {idx}: missing record_hash")
                chain_tainted = True
            elif actual_hash != expected_hash:
                errors.append(f"row {idx}: record_hash mismatch")
                chain_tainted = True

            if chain_tainted and idx < len(rows) - 1:
                warnings.append(
                    f"row {idx + 1}: downstream linkage follows a tainted chain segment"
                )

            previous_hash = actual_hash if actual_hash == expected_hash else expected_hash

        return {
            "exists": self.log_path.exists(),
            "event_count": len(rows),
            "valid": not errors,
            "errors": errors,
            "warnings": warnings,
            "latest_event_hash": previous_hash,
            "log_path": str(self.log_path),
        }

from __future__ import annotations

from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional
import hashlib
import json


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def canonical_json(payload: Dict[str, Any]) -> str:
    return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


@dataclass
class CanonRecord:
    canon_version: str
    canon_parent: Optional[str]
    canon_commit_summary: str
    canon_timestamp: str
    validation_artifact_reference: str
    governance_event_hash: str
    promotion_payload_hash: str
    runtime_seed_version: str
    notes: Optional[str] = None
    prev_lineage_hash: Optional[str] = None
    lineage_record_hash: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


class CanonLineageStore:
    """Append-only canon lineage with parent linkage and record hashing."""

    HASH_EXCLUDED_FIELDS = {"lineage_record_hash"}

    def __init__(self, lineage_path: str | Path, *, seed_committed_canon: bool = True):
        self.lineage_path = Path(lineage_path)
        self.seed_committed_canon = seed_committed_canon
        self.lineage_path.parent.mkdir(parents=True, exist_ok=True)

    def _rows(self) -> List[Dict[str, Any]]:
        if not self.lineage_path.exists():
            return []
        rows: List[Dict[str, Any]] = []
        with self.lineage_path.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line:
                    rows.append(json.loads(line))
        return rows

    def read_lineage(self) -> List[Dict[str, Any]]:
        return self._rows()

    def current_head(self) -> Optional[Dict[str, Any]]:
        rows = self._rows()
        return rows[-1] if rows else None

    def latest_lineage_hash(self) -> Optional[str]:
        head = self.current_head()
        return head.get("lineage_record_hash") if head else None

    def _record_payload_for_hash(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        return {k: v for k, v in payload.items() if k not in self.HASH_EXCLUDED_FIELDS}

    def _compute_record_hash(self, payload: Dict[str, Any]) -> str:
        return sha256_text(canonical_json(self._record_payload_for_hash(payload)))

    @staticmethod
    def _repo_root() -> Path:
        return Path(__file__).resolve().parents[4]

    def _seed_committed_canon_if_local_promotion(self) -> None:
        if not self.seed_committed_canon:
            return
        root = self._repo_root()
        try:
            self.lineage_path.resolve().relative_to((root / ".lumina_state").resolve())
        except ValueError:
            return
        committed = root / "artifacts/runtime_truth/current/canon_lineage_0001.jsonl"
        if not committed.is_file():
            raise ValueError("committed promotion lineage is missing")
        source = CanonLineageStore(committed, seed_committed_canon=False)
        if not source.verify_lineage()["valid"] or not source.read_lineage():
            raise ValueError("committed promotion lineage is invalid")
        rows = self._rows()
        if rows:
            if rows[:len(source.read_lineage())] != source.read_lineage() or not self.verify_lineage()["valid"]:
                raise ValueError("local lineage does not extend valid committed canon; use fresh promotion state")
            return
        self.lineage_path.write_bytes(committed.read_bytes())

    def _next_version(self) -> str:
        rows = self._rows()
        return f"canon-{len(rows)+1:04d}"

    def promote(
        self,
        *,
        canon_commit_summary: str,
        validation_artifact_reference: str,
        governance_event_hash: str,
        promotion_payload: Dict[str, Any],
        runtime_seed_version: str,
        notes: Optional[str] = None,
    ) -> Dict[str, Any]:
        self._seed_committed_canon_if_local_promotion()
        head = self.current_head()
        record = {
            "canon_version": self._next_version(),
            "canon_parent": head["canon_version"] if head else None,
            "canon_commit_summary": canon_commit_summary,
            "canon_timestamp": utc_now(),
            "validation_artifact_reference": validation_artifact_reference,
            "governance_event_hash": governance_event_hash,
            "promotion_payload_hash": sha256_text(canonical_json(dict(promotion_payload or {}))),
            "runtime_seed_version": runtime_seed_version,
            "notes": notes,
            "prev_lineage_hash": head.get("lineage_record_hash") if head else None,
        }
        record["lineage_record_hash"] = self._compute_record_hash(record)
        with self.lineage_path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(record) + "\n")
        return record

    def verify_lineage(self) -> Dict[str, Any]:
        rows = self._rows()
        errors: List[str] = []
        warnings: List[str] = []
        previous_hash: Optional[str] = None
        previous_version: Optional[str] = None
        seen_versions = set()
        lineage_tainted = False

        for idx, row in enumerate(rows):
            version = row.get("canon_version")
            if not version:
                errors.append(f"row {idx}: missing canon_version")
                lineage_tainted = True
            elif version in seen_versions:
                errors.append(f"row {idx}: duplicate canon_version {version}")
                lineage_tainted = True
            else:
                seen_versions.add(version)

            expected_parent = previous_version if idx > 0 else None
            if row.get("canon_parent") != expected_parent:
                errors.append(
                    f"row {idx}: canon_parent mismatch (expected {expected_parent}, got {row.get('canon_parent')})"
                )
                lineage_tainted = True

            if row.get("prev_lineage_hash") != previous_hash:
                errors.append(
                    f"row {idx}: prev_lineage_hash mismatch (expected {previous_hash}, got {row.get('prev_lineage_hash')})"
                )
                lineage_tainted = True

            actual_hash = row.get("lineage_record_hash")
            expected_hash = self._compute_record_hash(row)
            if not actual_hash:
                errors.append(f"row {idx}: missing lineage_record_hash")
                lineage_tainted = True
            elif actual_hash != expected_hash:
                errors.append(f"row {idx}: lineage_record_hash mismatch")
                lineage_tainted = True

            if lineage_tainted and idx < len(rows) - 1:
                warnings.append(
                    f"row {idx + 1}: downstream linkage follows a tainted lineage segment"
                )

            previous_hash = actual_hash if actual_hash == expected_hash else expected_hash
            previous_version = version

        return {
            "exists": self.lineage_path.exists(),
            "record_count": len(rows),
            "valid": not errors,
            "errors": errors,
            "warnings": warnings,
            "current_head": rows[-1]["canon_version"] if rows else None,
            "lineage_path": str(self.lineage_path),
        }
